%% Join the network from wifi_creds and serve the application's log over HTTP.
%% WiFi credentials come from wifi_creds (generated by atomvm/gen_wifi_creds.sh, or copied
%% from src/wifi_creds.erl.example; git-ignored), like every other app here.
%%
%% On an M5Stack Tab5 the radio is the on-board ESP32-C6, and its rail is an expander pin
%% (WLAN_PWR_EN: pin 0 of the PI4IOE5V6408 at 0x44) that nothing else drives. This app powers
%% it as its first act -- which is also the only moment that works: esp_hosted looks for the
%% C6's SDIO link for about five seconds from reset, starting before app_main, and the C6 needs
%% that time to boot. See docs/babytalk_config.md and atomvm/README.md ("A switched board part
%% on an expander pin").
%%
%% It then joins the AP and serves, on port 8080:
%%   GET /       an HTML page that follows the log (EventSource)
%%   GET /logs   the log itself, as a Server-Sent Events stream: curl -N http://<ip>:8080/logs
%%
%% The log is listen_demo's: a listener on the m5stack_tab5 preset reports what it hears, and
%% every line is exactly what listen_demo_responder:handle_info/2 would print to the console.
-module(tab5_wifi_log).
-export([start/0]).

-define(C6_ADDR, 16#44).  %% Tab5: the PI4IOE5V6408 whose pin 0 is WLAN_PWR_EN
-define(C6_PIN, 0).

-define(HTTP_PORT, 8080).

start() ->
    {ok, _} = tab5_wifi_log_sink:start_link(),
    power_c6(),
    {Ssid, Psk} = wifi_creds:get(),
    {ok, {Ip, _, _}} = network:wait_for_sta([{ssid, Ssid}, {psk, Psk}], 30000),
    serve(Ip),
    listener(),
    timer:sleep(infinity).

%% The C6's rail, before anything else. The I2C bus comes from the board's preset (the Tab5's
%% system I2C, SDA 31 / SCL 32), so only the expander's address and pin are named here.
power_c6() ->
    {ok, Preset} = babytalk:audio_preset(m5stack_tab5),
    I2c = maps:get(i2c, Preset),
    Result = babytalk:io_pin_set(I2c, ?C6_ADDR, ?C6_PIN, 1),
    tab5_wifi_log_sink:log("tab5_wifi_log: C6 rail on (expander 0x~s pin ~p) -> ~p~n",
                           [integer_to_list(?C6_ADDR, 16), ?C6_PIN, Result]),
    Result.

serve(Ip) ->
    Pid = http_server:start_server(?HTTP_PORT, [{"*", tab5_wifi_log_http, []}], [{inet_backend, inet}, {nodelay, true}]),
    tab5_wifi_log_sink:log("tab5_wifi_log: log on http://~s:~p/ -- and GET /logs as a stream~n",
                           [ip_to_string(Ip), ?HTTP_PORT]),
    Pid.

listener() ->
    case tab5_wifi_log_sup:start_link() of
        {ok, _Pid} ->
            tab5_wifi_log_sink:log("tab5_wifi_log: listening (listen_demo's log lines)~n", []);
        Error ->
            tab5_wifi_log_sink:log("tab5_wifi_log: listener failed: ~p~n", [Error])
    end,
    ok.

ip_to_string({A, B, C, D}) ->
    io_lib:format("~p.~p.~p.~p", [A, B, C, D]).

